    FUSION_MODES,
    REMOVED_FUSION_MODES,
    apply_sensor_fusion,
)


def _frame() -> pd.DataFrame:
    return pd.DataFrame(
        {
            "Patient_Id": ["p1", "p2"],
            "sensor_type": ["type_1", "type_2"],
            "Binary_Study_Group": [0, 1],
        }
    )


def test_default_mode_is_an_available_mode():
    """SW-589 L12: the default must be a mode that exists, not the removed 'late'."""
    import inspect

    default = inspect.signature(apply_sensor_fusion).parameters["mode"].default
    assert default in FUSION_MODES


def test_default_call_with_several_sensors_returns_data_unchanged():
    """SW-589 L12: calling with defaults on multi-sensor data used to raise NotImplementedError."""
    data = _frame()

    fused, extra = apply_sensor_fusion(data, ["type_1", "type_2"])

    pd.testing.assert_frame_equal(fused, data)
    assert extra is None


@pytest.mark.parametrize("mode", REMOVED_FUSION_MODES)
def test_removed_modes_still_raise_when_asked_for_explicitly(mode):
    with pytest.raises(NotImplementedError, match="no longer part of this tree"):
        apply_sensor_fusion(_frame(), ["type_1", "type_2"], mode=mode)
