                    f"{self.n_slices} disjoint validation slices "
                    f"(validation proportion {val_fraction:.3f})"
                )
        self._slices: Dict[Any, List[List[Any]]] = {}
        self._cursor = 0
        self._reshuffle()

    def _reshuffle(self) -> None:
        for grp, pool in self._pools.items():
            shuffled = list(pool)
            self._rng.shuffle(shuffled)
            self._slices[grp] = [
                list(chunk)
                for chunk in np.array_split(
                    np.array(shuffled, dtype=object), self.n_slices
                )
            ]

    def draw(self) -> Dict[Any, List[Any]]:
        if self._cursor >= self.n_slices:
            self._reshuffle()
            self._cursor = 0
        chosen = {grp: list(slices[self._cursor]) for grp, slices in self._slices.items()}
        self._cursor += 1
        return chosen

