def verify_partitions(
    permutations: Sequence[Mapping[str, Sequence[Any]]],
    patient_rows: Mapping[Any, np.ndarray],
    deep_check_permutations: int = 10,
) -> Dict[str, Any]:
    """Prove that no patient — and therefore no datapoint — crosses a split.

    Patient-level disjointness plus "every row belongs to exactly one patient"
    already implies datapoint-level disjointness. The row-index intersection is
    re-run explicitly on the first ``deep_check_permutations`` permutations as
    insurance against a bug in the patient-to-row mapping itself.
    """
    violations: List[Dict[str, Any]] = []
    splits = ("train", "validation", "test")
    for entry in permutations:
        perm = entry.get("permutation")
        sets = {s: set(entry.get(s, ())) for s in splits}
        for i, left in enumerate(splits):
            for right in splits[i + 1 :]:
                shared = sets[left] & sets[right]
                if shared:
                    violations.append(
                        {
                            "permutation": perm,
                            "splits": [left, right],
                            "level": "patient",
                            "n_shared": len(shared),
                            "examples": sorted(map(str, shared))[:10],
                        }
                    )
    checked_rows = 0
    for entry in list(permutations)[: max(0, deep_check_permutations)]:
        perm = entry.get("permutation")
        row_sets: Dict[str, np.ndarray] = {}
        for split in splits:
            members = [patient_rows[p] for p in entry.get(split, ()) if p in patient_rows]
            row_sets[split] = (
                np.concatenate(members) if members else np.empty(0, dtype=np.int64)
            )
        checked_rows += sum(len(v) for v in row_sets.values())
