def _leakage_section(audit: Mapping[str, Any]) -> List[str]:
    check = audit.get("leakage_check") or {}
    parts = ["<h2>3. Split integrity</h2>"]
    if check.get("passed"):
        parts.append(
            f'<div class="banner pass">PASS — no patient appears in more than one '
            f'split, across all {check.get("n_permutations_checked", 0)} permutations. '
            f'Datapoint-level intersection re-verified on '
            f'{check.get("n_permutations_deep_checked", 0)} permutations '
            f'({check.get("n_rows_deep_checked", 0):,} rows).</div>'
        )
    else:
        violations = check.get("violations", [])
        parts.append(
            f'<div class="banner fail">FAIL — {len(violations)} violation(s) found.</div>'
        )
        parts.append(_table(pd.DataFrame(violations)))
    table = split_size_table(audit)
    if not table.empty:
        parts.append("<h3>Split sizes</h3>")
        parts.append(
            _note(
                "When 'patients %' and 'datapoints %' disagree, the patient-level draw is "
                "hitting the requested proportion in people but not in rows — expected on "
                "trace-level data, worth knowing before reading any metric."
            )
        )
        parts.append(_table(table))
    return parts

