def load_pool(cfg: SiteStabilityConfig, *, verbose: bool = True) -> SelectionPool:
    """Load ``features_all.pkl`` for the run / sensor and build the one-vs-rest pool."""
    sensor_type = normalize_sensor_type(cfg.sensor_type)
    if cfg.run_dir is not None:
        run = load_run(None, Path(cfg.run_dir).expanduser().resolve())
        features_dir = resolve_feature_run(run, feature_run_name=cfg.feature_run_name).features_dir
    else:
        extracted = Path(cfg.extracted_path) if cfg.extracted_path else REPO_ROOT.parent / "extractions"
        run = load_run(extracted, cfg.run_name)
        features_dir = features_dir_for_sensors(run.run_path, sensor_type)
    features_all_path = features_dir / "features_all.pkl"
    if not features_all_path.is_file():
        raise FileNotFoundError(
            f"features_all.pkl not found at {features_all_path}. Run pipeline_v2_features.ipynb first."
        )

