def resolve_holdout_run_dir(
    run: PipelineRun,
    *,
    holdout_run_name: str | None = None,
    holdout_result: HoldoutResult | None = None,
) -> Path:
    """The named holdout run, the one just trained, or the newest completed one."""
    root = run.run_path / HOLDOUT_RUNS_DIR_NAME
    if holdout_result is not None:
        candidate = holdout_result.holdout_run_dir.resolve()
    elif holdout_run_name and holdout_run_name != "latest":
        candidate = (root / holdout_run_name).resolve()
        if root.resolve() not in candidate.parents:
            raise ValueError("model_reports.holdout_run_name must stay inside holdout_runs/")
    else:
        completed = [
            entry["path"]
            for entry in run.extra.get("holdout_runs") or []
            if entry.get("status") == "completed" and entry.get("path")
        ]
        if not completed:
            raise FileNotFoundError(f"No completed holdout run recorded in {run.run_path}")
        candidate = (run.run_path / completed[-1]).resolve()
    if not (candidate / "manifest.json").is_file():
        raise FileNotFoundError(f"{candidate} is not a holdout run (no manifest.json)")
    return candidate


